<?php
// Included by index.php after authentication and CSRF initialization.
if(!isset($db)){http_response_code(404);exit;}
function agentSetup(){global $db;$db->exec("CREATE TABLE IF NOT EXISTS onb_agents(user_id INT PRIMARY KEY,active TINYINT NOT NULL DEFAULT 1,code VARCHAR(32) NOT NULL UNIQUE)");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_leads(id INT AUTO_INCREMENT PRIMARY KEY,agent_id INT NOT NULL,trip_id INT NULL,name VARCHAR(150) NOT NULL,email VARCHAR(254) NOT NULL,stage VARCHAR(20) NOT NULL DEFAULT 'new',notes TEXT NOT NULL,followup DATE NULL,commission DECIMAL(12,2) NOT NULL DEFAULT 0,payout VARCHAR(20) NOT NULL DEFAULT 'pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(agent_id))");}
function agentActive($id){try{return (bool)q('SELECT active FROM onb_agents WHERE user_id=?',[$id])->fetchColumn();}catch(PDOException $e){return false;}}
function agentAction($action,$u,$admin){if(!$u||(!$admin&&!agentActive($u['id'])))throw new RuntimeException('Access denied.');
if($admin){agentSetup();agentExtrasSetup();}
if($action==='agent_reward'&&$admin){q('UPDATE onb_agent_rewards SET redeemed_at=CURRENT_TIMESTAMP WHERE agent_id=? AND reward_year=? AND milestone=? AND redeemed_at IS NULL',[(int)p('id'),(int)p('year'),(int)p('milestone')]);go('page=agents');}
if($action==='agent_rate'&&$admin){$rate=filter_var(p('rate'),FILTER_VALIDATE_FLOAT);$id=(int)p('id');if($rate===false||$rate<0||$rate>100000||!q('SELECT user_id FROM onb_agents WHERE user_id=?',[$id])->fetchColumn())throw new RuntimeException('Invalid rate');q('INSERT INTO onb_agent_rates(agent_id,rate) VALUES(?,?) ON DUPLICATE KEY UPDATE rate=VALUES(rate)',[$id,$rate]);}
elseif($action==='agent_enable'&&$admin){$id=q("SELECT id FROM users WHERE email=? AND role='traveller'",[strtolower(p('email'))])->fetchColumn();if(!$id)throw new RuntimeException('Account must register first.');q('INSERT INTO onb_agents(user_id,code) VALUES(?,?) ON DUPLICATE KEY UPDATE active=1',[$id,bin2hex(random_bytes(8))]);}
elseif($action==='agent_toggle'&&$admin){q('UPDATE onb_agents SET active=? WHERE user_id=?',[(int)(p('active')==='1'),(int)p('id')]);}
elseif($action==='agent_lead'&&!$admin){$trip=(int)p('trip_id');if($trip&&!q('SELECT id FROM trips WHERE id=? AND published=1',[$trip])->fetchColumn())throw new RuntimeException('Journey unavailable.');if(!filter_var(p('email'),FILTER_VALIDATE_EMAIL)||!p('name')||p('consent')!=='yes')throw new RuntimeException('Name, email and permission to contact are required.');q('INSERT INTO onb_agent_leads(agent_id,trip_id,name,email,notes) VALUES(?,?,?,?,?)',[$u['id'],$trip?:null,p('name'),p('email'),p('notes')]);}
elseif($action==='agent_update'){ $stage=p('stage');if(!in_array($stage,['new','contacted','qualified','won','lost'],true))throw new RuntimeException('Invalid stage.');$date=p('followup');if($date!==''&&(!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date)||!checkdate((int)substr($date,5,2),(int)substr($date,8,2),(int)substr($date,0,4))))throw new RuntimeException('Invalid date.');if($admin){$pay=p('payout');if(!in_array($pay,['pending','approved','paid'],true)||!is_numeric(p('commission'))||(float)p('commission')<0)throw new RuntimeException('Invalid commission.');$old=q('SELECT * FROM onb_agent_leads WHERE id=?',[(int)p('id')])->fetch();if(!$old||$old['payout']==='paid')throw new RuntimeException('Paid records are locked.');if($pay!=='pending'&&$stage!=='won')throw new RuntimeException('Only won leads qualify.');agentVerify($old,$stage,$pay,$date);}else{if($stage==='won')throw new RuntimeException('Administrator must verify wins.');q('UPDATE onb_agent_leads SET stage=?,notes=?,followup=? WHERE id=? AND agent_id=? AND payout=\'pending\' AND stage<>\'won\'',[$stage,p('notes'),$date?:null,(int)p('id'),$u['id']]);}}
else throw new RuntimeException('Access denied.');go('page=agents');}
function agentView($u,$admin){if(!$u||(!$admin&&!agentActive($u['id']))){http_response_code(403);echo '<h2>Agent access required</h2>';return;}if($admin)agentSetup();agentExtrasSetup();$rows=q('SELECT l.*,t.title,u.name AS agent_name FROM onb_agent_leads l LEFT JOIN trips t ON t.id=l.trip_id JOIN users u ON u.id=l.agent_id'.($admin?'':' WHERE l.agent_id=?').' ORDER BY l.id DESC',$admin?[]:[$u['id']])->fetchAll(PDO::FETCH_ASSOC);?>
<div class="agent-space"><span class="eyebrow">OUR NEXT BOARDING / PARTNER NETWORK</span><h1><?=$admin?'Agent management':'Your sales workspace'?></h1><p>Manage relationships, follow-ups and commission records.</p><div class="metrics"><?php foreach(['Leads'=>count($rows),'Won'=>count(array_filter($rows,fn($r)=>$r['stage']==='won')),'Approved CAD'=>number_format(array_sum(array_column(array_filter($rows,fn($r)=>$r['payout']==='approved'),'commission')),2),'Paid CAD'=>number_format(array_sum(array_column(array_filter($rows,fn($r)=>$r['payout']==='paid'),'commission')),2)] as $k=>$v):?><article><span><?=h($k)?></span><strong><?=h($v)?></strong></article><?php endforeach;?></div>
<?php if($admin):?><h2>Enable an agent</h2><?php form('agent_enable');field('email','Registered account email','','email');?><button>Enable agent</button></form><?php foreach(q('SELECT a.*,u.name,u.email FROM onb_agents a JOIN users u ON u.id=a.user_id') as $a):?><article><strong><?=h($a['name'])?></strong> · <?=h($a['email'])?> · <?=$a['active']?'Active':'Disabled'?><?php form('agent_toggle');?><input type="hidden" name="id" value="<?=(int)$a['user_id']?>"><input type="hidden" name="active" value="<?=$a['active']?0:1?>"><button><?=$a['active']?'Disable':'Enable'?></button></form></article><?php endforeach;else:?><details><summary>Add customer lead</summary><?php form('agent_lead');field('name','Customer name');field('email','Customer email','','email');?><label>Journey<select name="trip_id"><option value="0">General enquiry</option><?php foreach(q('SELECT id,title FROM trips WHERE published=1') as $t):?><option value="<?=(int)$t['id']?>"><?=h($t['title'])?></option><?php endforeach;?></select></label><?php area('notes','Notes');?><label><input type="checkbox" name="consent" value="yes" required> Customer has agreed to be contacted</label><button>Add lead</button></form></details><p><a href="?page=trips">Browse and share published journeys</a></p><?php endif;?>
<?php agentExtrasView($u,$admin);?><h2>Customer pipeline</h2><?php if(!$rows):?><p>No leads yet.</p><?php endif;foreach($rows as $r):?><details><summary><?=h($r['name'])?> · <?=h($r['stage'])?> · <?=h($r['title']??'General enquiry')?></summary><p><?=h($r['email'])?> · <?=h($r['agent_name'])?></p><p>Commission CAD <?=h($r['commission'])?> · <?=h($r['payout'])?></p><?php form('agent_update');?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><label>Stage<select name="stage"><?php foreach(['new','contacted','qualified','won','lost'] as $s):?><option <?=$r['stage']===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></label><label>Follow-up date<input type="date" name="followup" value="<?=h($r['followup'])?>"></label><?php area('notes','Notes',$r['notes']);if($admin):echo '<input type="hidden" name="commission" value="'.h($r['commission']).'"><p>Approve only a fully paid, non-refunded traveller sale. One lead represents one traveller. Approved sales are locked except for payout processing.</p>';?><label>Payout<select name="payout"><?php foreach(['pending','approved','paid'] as $s):?><option <?=$r['payout']===$s?'selected':''?>><?=h($s)?></option><?php endforeach;?></select></label><?php endif;?><button>Save lead</button></form></details><?php endforeach;?></div><?php }

function agentExtrasSetup(){global $db;$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_sales(lead_id INT PRIMARY KEY,agent_id INT NOT NULL,sale_year INT NOT NULL,ordinal INT NOT NULL,verified_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(agent_id,sale_year,ordinal)) ENGINE=InnoDB");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_rewards(agent_id INT NOT NULL,reward_year INT NOT NULL,milestone INT NOT NULL,earned_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,redeemed_at TIMESTAMP NULL,PRIMARY KEY(agent_id,reward_year,milestone)) ENGINE=InnoDB");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_rates(agent_id INT PRIMARY KEY,rate DECIMAL(10,2) NOT NULL DEFAULT 0)");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_referrals(enquiry_id INT PRIMARY KEY,lead_id INT NOT NULL UNIQUE)");$db->exec("CREATE TABLE IF NOT EXISTS onb_agent_reminders(lead_id INT NOT NULL,due DATE NOT NULL,sent_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(lead_id,due))");}
function agentReferralCapture(){if(isset($_GET['ref'])&&is_string($_GET['ref'])&&preg_match('/^[a-f0-9]{16}$/D',$_GET['ref'])){try{$id=q('SELECT user_id FROM onb_agents WHERE code=? AND active=1',[$_GET['ref']])->fetchColumn();if($id)$_SESSION['agent_ref']=['id'=>(int)$id,'until'=>time()+2592000];}catch(PDOException $e){}}}
function agentAttribute($enquiry,$trip){$ref=$_SESSION['agent_ref']??[];if(($ref['until']??0)<time())return;$id=(int)$ref['id'];if(!agentActive($id))return;global $db;q('INSERT INTO onb_agent_leads(agent_id,trip_id,name,email,notes) VALUES(?,?,?,?,?)',[$id,$trip?:null,p('name'),p('email'),'Website referral enquiry #'.$enquiry]);$lead=$db->lastInsertId();q('INSERT INTO onb_agent_referrals(enquiry_id,lead_id) VALUES(?,?)',[$enquiry,$lead]);unset($_SESSION['agent_ref']);}
function agentStatement($u,$admin){if(!$u||(!$admin&&!agentActive($u['id']))){http_response_code(403);exit;} $id=$admin?(int)($_GET['agent_id']??0):(int)$u['id'];header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="commission-statement.csv"');header('Cache-Control: no-store');$f=fopen('php://output','w');fputcsv($f,['Lead ID','Journey','Created','Commission CAD','Payout']);foreach(q("SELECT l.id,t.title,l.created_at,l.commission,l.payout FROM onb_agent_leads l LEFT JOIN trips t ON t.id=l.trip_id WHERE l.agent_id=? AND l.stage='won' ORDER BY l.id",[$id]) as $r){$title=(string)$r['title'];if(preg_match('/^[\\s]*[=+@-]/',$title))$title="'".$title;fputcsv($f,[$r['id'],$title,$r['created_at'],$r['commission'],$r['payout']]);}fclose($f);exit;}
function agentExtrasView($u,$admin){agentExtrasSetup();?><section class="onb-dash"><h2>Partner performance</h2><?php agentRewardsView($u,$admin);if($admin):foreach(q('SELECT a.user_id,u.name FROM onb_agents a JOIN users u ON u.id=a.user_id') as $a):?><p><?=h($a['name'])?> · <a href="?page=agent_statement&amp;agent_id=<?=(int)$a['user_id']?>">Download statement</a></p><?php endforeach;else:$code=q('SELECT code FROM onb_agents WHERE user_id=?',[$u['id']])->fetchColumn();?><label>Your referral link (copy and share)<input readonly value="<?=h('https://'.($_SERVER['HTTP_HOST']??'').$_SERVER['SCRIPT_NAME'].'?page=trips&ref='.$code)?>"></label><p><a href="?page=agent_statement">Download commission statement (CSV)</a></p><?php endif;?><h3>Follow-ups due</h3><?php foreach(q("SELECT l.id,l.name,l.followup FROM onb_agent_leads l WHERE l.followup<=CURRENT_DATE AND l.stage NOT IN ('won','lost')".($admin?'':' AND l.agent_id=?')." ORDER BY l.followup",$admin?[]:[$u['id']]) as $r):?><p><?=h($r['followup'].' · '.$r['name'])?></p><?php endforeach;?><h3>Leaderboard · verified wins</h3><div class="dash-table"><table><thead><tr><th>Rank</th><th>Partner</th><th>Wins</th></tr></thead><tbody><?php $rank=0;foreach(q("SELECT a.user_id,u.name,COUNT(l.id) wins FROM onb_agents a JOIN users u ON u.id=a.user_id LEFT JOIN onb_agent_leads l ON l.agent_id=a.user_id AND l.stage='won' AND l.payout IN ('approved','paid') AND EXISTS (SELECT 1 FROM onb_agent_sales v WHERE v.lead_id=l.id AND v.sale_year=YEAR(CURRENT_DATE)) WHERE a.active=1 GROUP BY a.user_id,u.name ORDER BY wins DESC,a.user_id") as $r):?><tr><td><?=++$rank?></td><td><?=h($admin?$r['name']:((int)$r['user_id']===(int)$u['id']?'You':'Partner '.$r['user_id']))?></td><td><?=h($r['wins'])?></td></tr><?php endforeach;?></tbody></table></div></section><?php }

function agentTierRate($n){return $n<=50?100:($n<=100?150:($n<=200?200:300));}
function agentYear(){return (int)(new DateTimeImmutable('now',new DateTimeZone('America/Vancouver')))->format('Y');}
function agentVerify($old,$stage,$pay,$date){global $db;$db->beginTransaction();try{
$id=(int)$old['id'];$agent=(int)$old['agent_id'];q('SELECT user_id FROM onb_agents WHERE user_id=? FOR UPDATE',[$agent])->fetch();$old=q('SELECT * FROM onb_agent_leads WHERE id=? FOR UPDATE',[$id])->fetch();
if(!$old||$old['payout']==='paid')throw new RuntimeException('Paid records are locked.');
if($old['payout']==='approved'&&($stage!=='won'||$pay==='pending'))throw new RuntimeException('Approved sales cannot be reversed here. Contact accounting for corrections.');
if($pay==='paid'&&$old['payout']!=='approved')throw new RuntimeException('Approve first.');
$commission=$old['payout']==='approved'?$old['commission']:0;
if($pay==='approved'&&$old['payout']==='pending'){
$year=agentYear();$n=1+(int)q('SELECT COALESCE(MAX(ordinal),0) FROM onb_agent_sales WHERE agent_id=? AND sale_year=?',[$agent,$year])->fetchColumn();
q('INSERT INTO onb_agent_sales(lead_id,agent_id,sale_year,ordinal) VALUES(?,?,?,?)',[$id,$agent,$year,$n]);$commission=agentTierRate($n);
if($n%100===0)q('INSERT INTO onb_agent_rewards(agent_id,reward_year,milestone) VALUES(?,?,?)',[$agent,$year,$n]);}
q('UPDATE onb_agent_leads SET stage=?,notes=?,followup=?,commission=?,payout=? WHERE id=?',[$stage,p('notes'),$date?:null,$commission,$pay,$id]);$db->commit();
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
function agentRewardsView($u,$admin){$year=agentYear();$agents=$admin?q('SELECT a.user_id,u.name FROM onb_agents a JOIN users u ON u.id=a.user_id')->fetchAll():[['user_id'=>$u['id'],'name'=>$u['name']]];?>
<h3>Annual partner rewards · <?=$year?></h3><p>Progressive CAD commissions: Silver 1–50 $100; Gold 51–100 $150; Platinum 101–200 $200; Diamond 201+ $300. One complimentary trip every 100 eligible sales. Calendar year resets January 1 (Pacific time).</p>
<p>Silver: referral tools and marketing materials. Gold: priority support and early package access. Platinum: personalised marketing, priority leads and dedicated account support. Diamond: priority payouts, luxury reward opportunities, potential paid tour hosting and featured partner opportunities. Diamond Elite recognition at 500 sales. Benefits subject to availability and company approval.</p>
<?php foreach($agents as $a):$id=(int)$a['user_id'];$n=(int)q('SELECT COUNT(*) FROM onb_agent_sales WHERE agent_id=? AND sale_year=?',[$id,$year])->fetchColumn();$tier=$n>=500?'Diamond Elite':($n>200?'Diamond':($n>100?'Platinum':($n>50?'Gold':'Silver')));$target=(int)(floor($n/100)+1)*100;?>
<article><h3><?=h($a['name'])?> · <?=h($tier)?></h3><p><?=$n?> verified sales · CAD $<?=agentTierRate($n+1)?> next sale · <?=$target-$n?> sales to next complimentary trip</p><progress max="100" value="<?=$n%100?>"></progress>
<?php foreach(q('SELECT * FROM onb_agent_rewards WHERE agent_id=? ORDER BY reward_year DESC,milestone DESC',[$id]) as $reward):?><p><?=h($reward['reward_year'])?> · <?=h($reward['milestone'])?> sales · Complimentary trip · <?=$reward['redeemed_at']?'Redeemed':'Available — contact team to arrange'?></p><?php if($admin&&!$reward['redeemed_at']):form('agent_reward');?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="year" value="<?=(int)$reward['reward_year']?>"><input type="hidden" name="milestone" value="<?=(int)$reward['milestone']?>"><button>Mark redeemed</button></form><?php endif;endforeach;?></article><?php endforeach;?><p>Rewards: selected departures, up to CAD $3,500 retail, non-transferable, no cash alternative; redeem within 12 months of earning. Historical commissions remain unchanged.</p><?php }
